"""In-place foreach sign: ``aten::_foreach_sign_(Tensor(a!)[] self) -> ()``.

Every element of every tensor in the list is replaced by its sign, in place.
The kernels work on the tensors' existing storage; no output is allocated and
no layout conversion is performed.

Tensors are grouped by ``(device, dtype, layout class)``.  All flat tensors of
one group are handled by a *single* kernel launch whose grid axis 0 carries the
tensor index, because a launch on this platform costs far more than the element
work of a small tensor.
"""

import torch
import triton
import triton.language as tl

# ---------------------------------------------------------------------------
# element math
# ---------------------------------------------------------------------------


@triton.jit
def _sign_value(x):
    """sign(x) in the element's own dtype, using two compares and one subtract.

    Keeping the expression this short matters: every intermediate is a
    BLOCK-sized buffer in the vector core's unified buffer, and a
    ``tl.where`` chain (constants, ``x * 0``, two selects) needs several more of
    them, which caps the usable tile size.
    """
    if x.dtype == tl.int1:
        return x
    elif x.dtype == tl.bfloat16:
        # Triton promotes bfloat16 arithmetic to fp32, so the natural
        # ``(x > 0) - (x < 0)`` lowering costs two bf16->fp32 conversions for
        # the compares, two i1->bf16 conversions, two more bf16->fp32
        # conversions for the subtract and one fp32->bf16 conversion -- nine
        # vector instructions whose fp32 intermediates (32 KB each at 8192
        # elements) fill the unified buffer and forbid a larger tile.
        #
        # IEEE-754 sign is a property of the bit pattern, so the same value is
        # produced with 16-bit integer work instead: +-0 and NaN map to 0,
        # everything else becomes +-1 through the sign bit.  That is exactly
        # the semantics of the compare form, at half the buffer width.
        bits = x.to(tl.int16, bitcast=True)
        mag = bits & 0x7FFF
        valid = (mag != 0) & (mag < 0x7F81)  # reject zero and NaN
        patt = (bits & -32768) | 0x3F80  # copysign(1.0, x) in bf16 bits
        return tl.where(valid, patt, 0).to(tl.int16).to(tl.bfloat16, bitcast=True)
    return (x > 0).to(x.dtype) - (x < 0).to(x.dtype)


# ---------------------------------------------------------------------------
# kernels
# ---------------------------------------------------------------------------


@triton.jit
def _sign_tiles(
    x_ptr, n_elements, tile_id, tile_count, BLOCK: tl.constexpr, TAIL: tl.constexpr
):
    """Walk BLOCK-sized tiles of one tensor from tile ``tile_id`` of ``tile_count``.

    The whole tiles are visited without a mask so the hot loop issues full-width
    transfers and carries no per-element bounds compare.  The trailing partial
    tile is walked in small TAIL-sized steps by the first tile of the group, so
    the large tile's buffers are not duplicated just to cover a remainder.
    """
    full = (n_elements // BLOCK) * BLOCK
    base = tile_id * BLOCK
    step = tile_count * BLOCK
    for start in range(base, full, step):
        offs = start + tl.arange(0, BLOCK)
        tl.store(x_ptr + offs, _sign_value(tl.load(x_ptr + offs)))
    if tile_id == 0:
        for start in range(full, n_elements, TAIL):
            offs = start + tl.arange(0, TAIL)
            mask = offs < n_elements
            tl.store(
                x_ptr + offs,
                _sign_value(tl.load(x_ptr + offs, mask=mask)),
                mask=mask,
            )


@triton.jit
def _sign_flat_kernel(x_ptr, n_elements, BLOCK: tl.constexpr):
    """One tensor whose storage span is exactly ``numel`` items."""
    _sign_tiles(x_ptr, n_elements, tl.program_id(0), tl.num_programs(0), BLOCK, 1024)


