@triton.jit
def _sign_strided_kernel(
    x_ptr,
    n_elements,
    s0,
    s1,
    s2,
    s3,
    t0,
    t1,
    t2,
    t3,
    RANK: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """Generic strided pass for views with holes (``x[:, ::2]`` and friends).

    ``s*``/``t*`` are the effective sizes/strides, outermost first, after the
    host merged dimensions that are contiguous with each other.
    """
    start = tl.program_id(0) * BLOCK
    step = tl.num_programs(0) * BLOCK
    for base in range(start, n_elements, step):
        offs = base + tl.arange(0, BLOCK)
        mask = offs < n_elements
        if RANK == 1:
            off = (offs % s0) * t0
        elif RANK == 2:
            off = (offs % s1) * t1 + ((offs // s1) % s0) * t0
        elif RANK == 3:
            off = (
                (offs % s2) * t2
                + ((offs // s2) % s1) * t1
                + ((offs // (s2 * s1)) % s0) * t0
            )
        else:
            off = (
                (offs % s3) * t3
                + ((offs // s3) % s2) * t2
                + ((offs // (s3 * s2)) % s1) * t1
                + ((offs // (s3 * s2 * s1)) % s0) * t0
            )
        x = tl.load(x_ptr + off, mask=mask)
        tl.store(x_ptr + off, _sign_value(x), mask=mask)


# ---------------------------------------------------------------------------
# host side
# ---------------------------------------------------------------------------

# Elements per tile.  float16/float32 use 32 KB of payload so the fixed
# per-iteration cost (flag set/wait pairs, pointer arithmetic, loop branch) is
# amortised over twice the bytes; bfloat16 stays at 16 KB because its element
# math needs more than one buffer per element and a 32 KB tile overflows the
# 192 KB unified buffer.  Depth 2 keeps the larger tile inside the buffer.
_BLOCK = {
    torch.float16: 16384,
    torch.bfloat16: 8192,
    torch.float32: 8192,
    torch.int8: 32768,
    torch.uint8: 32768,
    torch.int16: 16384,
    torch.int32: 8192,
    torch.int64: 4096,
    torch.bool: 32768,
}
_DEFAULT_BLOCK = 4096

# Single-buffered tiles.  A deeper multi-buffer chain measured neutral, and the
# second buffer set is what forbade a 32 KB tile: with one buffer set the larger
# tile fits, halving the fixed per-iteration cost (flag set/wait pairs, pointer
# arithmetic, loop branch) per byte moved.
_STAGES = {}

# Upper bound on resident programs per launch.  It shapes the work; every launch
# still derives its grid from the tensors' own element counts.
_MAX_PROGRAMS = 1024
_MAX_RANK = 4
_MAX_BATCH = 16


def _collapse_dims(shape, strides):
    """Merge adjacent dimensions that are contiguous with each other.

    The merged dimension keeps the *inner* stride, which is what turns a view
    like ``x[:, ::2]`` into one strided run of ``numel`` elements.
    """
    out_shape = []
    out_strides = []
    for size, stride in zip(shape, strides):
        if size == 1:
            continue
        if out_shape and out_strides[-1] == stride * size:
            out_shape[-1] *= size
            out_strides[-1] = stride
        else:
            out_shape.append(size)
            out_strides.append(stride)
    return out_shape, out_strides


def _launch_flat(t, numel, block, stages):
    grid = (min((numel + block - 1) // block, _MAX_PROGRAMS),)
    _sign_flat_kernel[grid](t, numel, BLOCK=block, num_stages=stages)


def _launch_strided(t, numel, block):
    shape, strides = _collapse_dims(t.shape, t.stride())
    rank = len(shape)
    if rank > _MAX_RANK:
        raise NotImplementedError(
            "foreach_sign_ supports at most %d effective dimensions" % _MAX_RANK
        )
    shape = shape + [1] * (_MAX_RANK - rank)
    strides = strides + [0] * (_MAX_RANK - rank)
    grid = (min((numel + block - 1) // block, _MAX_PROGRAMS),)
    _sign_strided_kernel[grid](
        t,
        numel,
        shape[0],
        shape[1],
        shape[2],
        shape[3],
        strides[0],
        strides[1],
        strides[2],
        strides[3],
        RANK=rank,
        BLOCK=block,
    )


def _launch_batch(pairs, nt, block, stages):
    """One launch for ``nt`` flat tensors given as ``[t0, n0, t1, n1, ...]``."""
    items = list(pairs)
    if len(items) < 2 * _MAX_BATCH:
        items += [items[0], 0] * ((2 * _MAX_BATCH - len(items)) // 2)
    max_numel = max(pairs[1::2])
    per_tensor = min((max_numel + block - 1) // block, max(1, _MAX_PROGRAMS // nt))
    _sign_batch_kernel[(nt, per_tensor)](*items, NT=nt, BLOCK=block, num_stages=stages)


def _is_flat(t):
    """True when the tensor's elements are a bijection onto its storage span."""
    if t.is_contiguous():
        return True
    if t.numel() <= 1:
        return True
    expected = 1
    for size, stride in sorted(zip(t.shape, t.stride()), key=lambda pair: pair[1]):
        if size == 1:
            continue
        if stride != expected:
            return False
        expected *= size
    return True


def foreach_sign_(self):
    tensors = self
    if not isinstance(tensors, (list, tuple)):
        raise TypeError("argument 'self' must be tuple of Tensors")
    if not tensors:
        raise RuntimeError("Tensor list must have at least one tensor.")

    groups = {}
    for t in tensors:
        numel = t.numel()
        if numel == 0:
            continue
        dtype = t.dtype
        if dtype.is_complex:
            raise RuntimeError(
                "\"foreach\" not implemented for '%s'"
                % str(dtype).replace("torch.", "")
            )
        key = (t.device, dtype, _is_flat(t))
        group = groups.get(key)
        if group is None:
            groups[key] = [t, numel]
        else:
            group.append(t)
            group.append(numel)

    for (device, dtype, flat), group in groups.items():
        block = _BLOCK.get(dtype, _DEFAULT_BLOCK)
        stages = _STAGES.get(dtype, 1)
        size = len(group)
        if not flat:
            for i in range(0, size, 2):
                _launch_strided(group[i], group[i + 1], block)
        elif size == 2:
            _launch_flat(group[0], group[1], block, stages)
        else:
            nt = size >> 1
            if nt <= _MAX_BATCH:
                _launch_batch(group, nt, block, stages)
            else:
                for i in range(0, size, 2 * _MAX_BATCH):
                    _launch_batch(
                        group[i : i + 2 * _MAX_BATCH],
                        min(_MAX_BATCH, (size - i) >> 1),
                        block,
                        stages,
                    )
    return None
